diff --git a/AGENTS.md b/AGENTS.md
index 348a42f8..31fca1b4 100644
--- a/AGENTS.md
+++ b/AGENTS.md
@@ -13,6 +13,12 @@
 ## Entire CLI
 - Set `ENTIRE_TOKEN_STORE=file` in the environment before running any `entire` command (for example, `export ENTIRE_TOKEN_STORE=file`).

+## Pre-commit and pre-push review (required)
+- Both review agents run on all finished work, before it is committed and before it is submitted to the remote. Stage the change and run `scripts/precommit-review.sh --staged` before every commit; run `scripts/precommit-review.sh` on the final HEAD before every `git push`. The script runs two read-only reviewer agents on the net change against the merge-base with `origin/main`: `slop-reviewer` (rates slop Low/Medium/Large with concrete findings) and `defect-reviewer` (bugs, regressions, missing guards the change introduces). Their prompts are in `.claude/agents/`.
+- The review passes only when slop is rated Low with zero findings and the defect reviewer reports none. Fix every finding, restage and rerun until it passes. Do not dismiss a finding without evidence from the code, and never edit the verdict file.
+- A Claude Code `PreToolUse` hook (`scripts/precommit-review-gate.mjs`, wired in `.claude/settings.json`) blocks `git commit` unless the exact tree being committed has a passing verdict, and blocks `git push` unless the tree of HEAD has one. Verdicts live in `$(git rev-parse --git-common-dir)/precommit-review/<tree>.json`. Any change to the tree, including a merge of `origin/main`, needs a fresh review.
+- The review costs two model runs: run it on the finished change, not on every keystroke. Entire's own review applies the same standards on the PR, so a change that passes here should arrive at Entire with no findings.
+
 ## v1.0.0 work and concurrent agents
 - The v1.0.0 plan is in `docs/v1.0.0/` (start at `docs/v1.0.0/README.md`). Implement one claimed PR slice at a time, within the safe change boundary in its plan.
 - When more than one agent may be working, follow `docs/v1.0.0/CONCURRENCY.md`. In short:
diff --git a/scripts/precommit-review-gate.mjs b/scripts/precommit-review-gate.mjs
new file mode 100755
index 00000000..993b1be3
--- /dev/null
+++ b/scripts/precommit-review-gate.mjs
@@ -0,0 +1,119 @@
+#!/usr/bin/env node
+// Claude Code PreToolUse hook for Bash: block `git commit` and `git push` unless the tree involved has a passing review verdict
+// (slop-reviewer and defect-reviewer both clean) made against the current merge-base with origin/main.
+// The verdict is written by scripts/precommit-review.sh. Commit: the tree about to be committed. Push: the tree of HEAD, so work is
+// reviewed after it is completed and before it reaches the remote. Reads the hook JSON on stdin; exit 2 blocks the tool call.
+import { execFileSync } from "node:child_process";
+import fs from "node:fs";
+import os from "node:os";
+import path from "node:path";
+
+const input = JSON.parse(fs.readFileSync(0, "utf8"));
+const command = String(input.tool_input?.command ?? "");
+const startDir = input.cwd && fs.existsSync(input.cwd) ? input.cwd : process.cwd();
+
+const block = (message) => { console.error(`Blocked: ${message}`); process.exit(2); };
+
+// Split a shell command line into simple commands made of words (single and double quotes honoured, no expansion).
+function simpleCommands(line) {
+  const commands = [];
+  let words = [];
+  let word = "";
+  let has = false;
+  let quote = "";
+  const endWord = () => { if (has) words.push(word); word = ""; has = false; };
+  const endCommand = () => { endWord(); if (words.length) commands.push(words); words = []; };
+  for (let i = 0; i < line.length; i++) {
+    const c = line[i];
+    if (quote) {
+      if (c === quote) quote = "";
+      else if (c === "\\" && quote === '"' && i + 1 < line.length) word += line[++i];
+      else word += c;
+    } else if (c === "'" || c === '"') { quote = c; has = true; }
+    else if (c === "\\" && i + 1 < line.length) { word += line[++i]; has = true; }
+    else if (/\s/.test(c)) { if (c === "\n") endCommand(); else endWord(); }
+    else if (c === ";" || c === "&" || c === "|" || c === "(" || c === ")") endCommand();
+    else { word += c; has = true; }
+  }
+  endCommand();
+  return commands;
+}
+
+// Parse `git [global options] <verb> <args>`; returns null when the words are not a git command.
+const GLOBAL_WITH_VALUE = new Set(["-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path", "--super-prefix", "--config-env"]);
+function parseGit(words) {
+  const first = words.findIndex((w) => path.basename(w) === "git");
+  if (first !== 0) return null;
+  let dir = startDir;
+  let i = 1;
+  for (; i < words.length && words[i].startsWith("-"); i++) {
+    const w = words[i];
+    if (w === "-C") { dir = path.resolve(dir, words[++i] ?? "."); continue; }
+    if (GLOBAL_WITH_VALUE.has(w)) { i++; continue; }
+  }
+  return { dir, verb: words[i], args: words.slice(i + 1) };
+}
+
+const INDEX_CHANGERS = new Set(["add", "rm", "mv", "reset", "checkout", "restore", "stash", "apply", "merge", "rebase", "cherry-pick", "revert", "am", "pull", "switch", "clean"]);
+const COMMIT_VALUE_OPTIONS = new Set(["-m", "--message", "-F", "--file", "-C", "--reuse-message", "-c", "--reedit-message", "--author", "--date", "-S", "--gpg-sign", "--cleanup", "-t", "--template", "--fixup", "--squash", "--trailer", "--pathspec-from-file"]);
+
+const parsed = simpleCommands(command).map(parseGit);
+const gits = parsed.filter(Boolean);
+const commitIndex = gits.findIndex((g) => g.verb === "commit");
+const pushIndex = gits.findIndex((g) => g.verb === "push");
+if (commitIndex < 0 && pushIndex < 0) process.exit(0);
+
+const isCommit = commitIndex >= 0;
+const target = gits[isCommit ? commitIndex : pushIndex];
+const git = (args, env = {}) => execFileSync("git", args, { cwd: target.dir, env: { ...process.env, ...env }, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
+
+if (isCommit) {
+  // The hook runs before the whole command, so the index it can see may differ from the one the commit will use.
+  if (gits.slice(0, commitIndex).some((g) => INDEX_CHANGERS.has(g.verb))) {
+    block("`git commit` is chained after a command that changes the index. Run that command first, then run the review, then commit on its own.");
+  }
+  let all = false;
+  for (let i = 0; i < target.args.length; i++) {
+    const a = target.args[i];
+    if (a === "--") block("`git commit -- <paths>` commits a tree other than the reviewed index. Stage the files, review, then run a plain `git commit`.");
+    if (a === "-a" || a === "--all") all = true;
+    else if (a === "-i" || a === "--include" || a === "-o" || a === "--only" || a === "--interactive" || a === "-p" || a === "--patch") block(`\`git commit ${a}\` commits a tree other than the reviewed index. Stage the files, review, then run a plain \`git commit\`.`);
+    else if (COMMIT_VALUE_OPTIONS.has(a)) i++;
+    else if (a.startsWith("--")) { /* long option with =value or flag */ }
+    else if (a.startsWith("-")) { if (/^-[a-zA-Z]*a[a-zA-Z]*$/.test(a)) all = true; }
+    else block("`git commit <paths>` commits a tree other than the reviewed index. Stage the files, review, then run a plain `git commit`.");
+  }
+  target.all = all;
+}
+
+let tree;
+let common;
+let mergeBase;
+try {
+  common = git(["rev-parse", "--path-format=absolute", "--git-common-dir"]);
+  mergeBase = git(["merge-base", "origin/main", "HEAD"]);
+  if (!isCommit) {
+    tree = git(["rev-parse", "HEAD^{tree}"]);
+  } else if (target.all) {
+    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "precommit-gate-"));
+    try {
+      const tmp = path.join(dir, "index");
+      fs.copyFileSync(git(["rev-parse", "--path-format=absolute", "--git-path", "index"]), tmp);
+      git(["add", "-u"], { GIT_INDEX_FILE: tmp });
+      tree = git(["write-tree"], { GIT_INDEX_FILE: tmp });
+    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
+  } else {
+    tree = git(["write-tree"]);
+  }
+} catch {
+  process.exit(0); // not a git checkout (or no origin/main): let git report it
+}
+
+const verdictPath = path.join(common, "precommit-review", `${tree}.json`);
+let verdict = null;
+try { verdict = JSON.parse(fs.readFileSync(verdictPath, "utf8")); } catch { /* no verdict */ }
+if (verdict?.pass === true && verdict.base === mergeBase) process.exit(0);
+
+block(`no passing review (slop-reviewer and defect-reviewer) of the tree you are about to ${isCommit ? "commit" : "push"} (${tree}) against the merge-base ${mergeBase.slice(0, 12)}.
+${isCommit ? "Stage your change, then run: scripts/precommit-review.sh --staged" : "Run on the finished work before it goes to the remote: scripts/precommit-review.sh"}
+Fix every finding it reports (it passes only when slop is rated Low with zero findings and the defect reviewer reports none), then retry.${verdict ? `\nLast verdict for this exact tree: ${verdictPath} (pass=${verdict.pass}, base ${String(verdict.base).slice(0, 12)})` : ""}`);
diff --git a/scripts/precommit-review.sh b/scripts/precommit-review.sh
new file mode 100755
index 00000000..de81c698
--- /dev/null
+++ b/scripts/precommit-review.sh
@@ -0,0 +1,112 @@
+#!/usr/bin/env bash
+# Run both review agents on the net change that is about to be committed (or on HEAD) and record the verdict:
+#   slop-reviewer    rates the slop the change adds (Low/Medium/Large) and lists concrete slop findings
+#   defect-reviewer  lists the bugs, regressions and missing guards the change introduces
+# Usage: scripts/precommit-review.sh [--staged] [--intent <text>]
+#   --staged  review the staged tree against the merge-base with origin/main (run before `git commit`; this is what the commit gate checks)
+#   (default) review HEAD against the merge-base with origin/main
+#   --intent  what the change is meant to do (default: the subjects of the commits on this branch since the base)
+# The verdict for the tree is stored in $(git rev-parse --git-common-dir)/precommit-review/<tree-sha>.json and records the base it was
+# made against; the commit/push gate only accepts a verdict whose base is the current merge-base.
+# Exit 0 only when slop is rated Low with no findings AND the defect reviewer reports none.
+set -euo pipefail
+
+staged=0; intent=""
+while [[ $# -gt 0 ]]; do
+  case "$1" in
+    --staged) staged=1; shift ;;
+    --intent) intent="${2:?--intent needs text}"; shift 2 ;;
+    *) echo "usage: $0 [--staged] [--intent <text>]" >&2; exit 64 ;;
+  esac
+done
+
+command -v claude >/dev/null || { echo "precommit-review: the claude CLI is required" >&2; exit 2; }
+command -v node >/dev/null || { echo "precommit-review: node is required" >&2; exit 2; }
+
+root=$(git rev-parse --show-toplevel)
+common=$(git rev-parse --path-format=absolute --git-common-dir)
+cd "$root"
+base=$(git merge-base origin/main HEAD)
+[[ -n "$intent" ]] || intent="Commits on this branch since the base: $(git log --format=%s "$base"..HEAD | head -n 10 | paste -sd ';' - | cut -c1-600)"
+
+if [[ $staged -eq 1 ]]; then
+  tree=$(git write-tree)
+  diff_cmd="git diff --cached $base"
+  head_desc="the staged tree $tree (not yet committed)"
+  read_note="The staged content is the subject: read a file as staged with \`git show :<path>\`; the working tree may contain unstaged edits that are NOT part of the change."
+else
+  tree=$(git rev-parse 'HEAD^{tree}')
+  diff_cmd="git diff $base HEAD"
+  head_desc="HEAD $(git rev-parse --short HEAD)"
+  read_note="Read a file as committed with \`git show HEAD:<path>\`."
+fi
+
+context=$(cat <<CTX
+Review context.
+Diff base: $base (the merge-base with origin/main; its commit message describes unrelated earlier work, not this change).
+Head: $head_desc.
+Intent of the change: $intent
+$read_note
+Command to read the full diff: $diff_cmd
+Command to read one file: $diff_cmd -- <path>
+Read a file as it is at the diff base: git show $base:<path>
+Repository instructions: AGENTS.md at the repository root.
+
+Changed files (stat):
+$($diff_cmd --stat | tail -n 40)
+
+Patch (truncated at 200000 bytes; read the rest with the command above):
+$($diff_cmd | head -c 200000)
+CTX
+)
+
+work=$(mktemp -d)
+trap 'rm -rf "$work"' EXIT
+review() { # $1 agent
+  claude -p --agent "$1" --output-format json \
+    --allowedTools "Read" "Glob" "Grep" "Bash(git diff:*)" "Bash(git log:*)" "Bash(git show:*)" "Bash(git status:*)" "Bash(rg:*)" \
+    <<<"$context" >"$work/$1.json"
+}
+review slop-reviewer & slop_pid=$!
+review defect-reviewer & defect_pid=$!
+trap 'kill "$slop_pid" "$defect_pid" 2>/dev/null || true; rm -rf "$work"' EXIT
+wait "$slop_pid" || { echo "precommit-review: slop-reviewer failed" >&2; exit 3; }
+wait "$defect_pid" || { echo "precommit-review: defect-reviewer failed" >&2; exit 3; }
+
+mkdir -p "$common/precommit-review"
+verdict="$common/precommit-review/$tree.json"
+node - "$work" "$verdict" "$tree" "$base" <<'JS'
+const fs = require("fs");
+const [work, verdictPath, tree, base] = process.argv.slice(2);
+function load(agent) {
+  const text = String(JSON.parse(fs.readFileSync(`${work}/${agent}.json`, "utf8")).result ?? "").trimEnd();
+  // The verdict is the last fenced json block. Finding text may itself contain ``` so cut from the last opening fence to the final closing fence.
+  const open = text.lastIndexOf("```json");
+  const close = text.lastIndexOf("```");
+  if (open < 0 || close <= open) { keepRaw(agent); console.error(`precommit-review: ${agent} returned no JSON verdict block`); process.exit(3); }
+  try {
+    return { text: text.slice(0, open).trim(), verdict: JSON.parse(text.slice(open + "```json".length, close)) };
+  } catch (error) {
+    keepRaw(agent); console.error(`precommit-review: ${agent} verdict is not valid JSON (${error.message})`); process.exit(3);
+  }
+}
+function keepRaw(agent) {
+  const kept = `${verdictPath}.${agent}.raw.json`;
+  fs.copyFileSync(`${work}/${agent}.json`, kept);
+  console.error(`precommit-review: raw ${agent} reply kept at ${kept}`);
+}
+const slop = load("slop-reviewer");
+const defects = load("defect-reviewer");
+if (!["Low", "Medium", "Large"].includes(slop.verdict.rating) || !Array.isArray(slop.verdict.findings) || !Array.isArray(defects.verdict.findings)) {
+  console.error("precommit-review: malformed verdict"); process.exit(3);
+}
+const slopPass = slop.verdict.rating === "Low" && slop.verdict.findings.length === 0;
+const defectPass = defects.verdict.findings.length === 0;
+const pass = slopPass && defectPass;
+fs.writeFileSync(verdictPath, JSON.stringify({ tree, base, pass, slop: { pass: slopPass, ...slop.verdict }, defects: { pass: defectPass, ...defects.verdict }, at: new Date().toISOString() }, null, 2));
+console.log(`== slop-reviewer ==\n${slop.text}\n\n== defect-reviewer ==\n${defects.text}\n`);
+console.log(`precommit-review: slop ${slop.verdict.rating} (${slop.verdict.findings.length} finding(s)), defects ${defects.verdict.findings.length} -> ${pass ? "PASS" : "FAIL"} (${verdictPath})`);
+for (const f of slop.verdict.findings) console.log(`  slop ${f.severity ?? "?"} ${f.file}:${f.line} ${f.summary}`);
+for (const f of defects.verdict.findings) console.log(`  defect ${f.severity ?? "?"} ${f.file}:${f.line} (${f.confidence ?? "?"}) ${String(f.body ?? "").split("\n")[0]}`);
+process.exit(pass ? 0 : 1);
+JS

