@@ -0,0 +1,119 @@
+#!/usr/bin/env node
+// Claude Code PreToolUse hook for Bash: block `git commit` and `git push` unless the tree involved has a passing review verdict
+// (slop-reviewer and defect-reviewer both clean) made against the current merge-base with origin/main.
+// The verdict is written by scripts/precommit-review.sh. Commit: the tree about to be committed. Push: the tree of HEAD, so work is
+// reviewed after it is completed and before it reaches the remote. Reads the hook JSON on stdin; exit 2 blocks the tool call.
+import { execFileSync } from "node:child_process";
+import fs from "node:fs";
+import os from "node:os";
+import path from "node:path";
+
+const input = JSON.parse(fs.readFileSync(0, "utf8"));
+const command = String(input.tool_input?.command ?? "");
+const startDir = input.cwd && fs.existsSync(input.cwd) ? input.cwd : process.cwd();
+
+const block = (message) => { console.error(`Blocked: ${message}`); process.exit(2); };
+
+// Split a shell command line into simple commands made of words (single and double quotes honoured, no expansion).
+function simpleCommands(line) {
+  const commands = [];
+  let words = [];
+  let word = "";
+  let has = false;
+  let quote = "";
+  const endWord = () => { if (has) words.push(word); word = ""; has = false; };
+  const endCommand = () => { endWord(); if (words.length) commands.push(words); words = []; };
+  for (let i = 0; i < line.length; i++) {
+    const c = line[i];
+    if (quote) {
+      if (c === quote) quote = "";
+      else if (c === "\\" && quote === '"' && i + 1 < line.length) word += line[++i];
+      else word += c;
+    } else if (c === "'" || c === '"') { quote = c; has = true; }
+    else if (c === "\\" && i + 1 < line.length) { word += line[++i]; has = true; }
+    else if (/\s/.test(c)) { if (c === "\n") endCommand(); else endWord(); }
+    else if (c === ";" || c === "&" || c === "|" || c === "(" || c === ")") endCommand();
+    else { word += c; has = true; }
+  }
+  endCommand();
+  return commands;
+}
+
+// Parse `git [global options] <verb> <args>`; returns null when the words are not a git command.
+const GLOBAL_WITH_VALUE = new Set(["-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path", "--super-prefix", "--config-env"]);
+function parseGit(words) {
+  const first = words.findIndex((w) => path.basename(w) === "git");
+  if (first !== 0) return null;
+  let dir = startDir;
+  let i = 1;
+  for (; i < words.length && words[i].startsWith("-"); i++) {
+    const w = words[i];
+    if (w === "-C") { dir = path.resolve(dir, words[++i] ?? "."); continue; }
+    if (GLOBAL_WITH_VALUE.has(w)) { i++; continue; }
+  }
+  return { dir, verb: words[i], args: words.slice(i + 1) };
+}
+
+const INDEX_CHANGERS = new Set(["add", "rm", "mv", "reset", "checkout", "restore", "stash", "apply", "merge", "rebase", "cherry-pick", "revert", "am", "pull", "switch", "clean"]);
+const COMMIT_VALUE_OPTIONS = new Set(["-m", "--message", "-F", "--file", "-C", "--reuse-message", "-c", "--reedit-message", "--author", "--date", "-S", "--gpg-sign", "--cleanup", "-t", "--template", "--fixup", "--squash", "--trailer", "--pathspec-from-file"]);
+
+const parsed = simpleCommands(command).map(parseGit);
+const gits = parsed.filter(Boolean);
+const commitIndex = gits.findIndex((g) => g.verb === "commit");
+const pushIndex = gits.findIndex((g) => g.verb === "push");
+if (commitIndex < 0 && pushIndex < 0) process.exit(0);
+
+const isCommit = commitIndex >= 0;
+const target = gits[isCommit ? commitIndex : pushIndex];
+const git = (args, env = {}) => execFileSync("git", args, { cwd: target.dir, env: { ...process.env, ...env }, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
+
+if (isCommit) {
+  // The hook runs before the whole command, so the index it can see may differ from the one the commit will use.
+  if (gits.slice(0, commitIndex).some((g) => INDEX_CHANGERS.has(g.verb))) {
+    block("`git commit` is chained after a command that changes the index. Run that command first, then run the review, then commit on its own.");
+  }
+  let all = false;
+  for (let i = 0; i < target.args.length; i++) {
+    const a = target.args[i];
+    if (a === "--") block("`git commit -- <paths>` commits a tree other than the reviewed index. Stage the files, review, then run a plain `git commit`.");
+    if (a === "-a" || a === "--all") all = true;
+    else if (a === "-i" || a === "--include" || a === "-o" || a === "--only" || a === "--interactive" || a === "-p" || a === "--patch") block(`\`git commit ${a}\` commits a tree other than the reviewed index. Stage the files, review, then run a plain \`git commit\`.`);
+    else if (COMMIT_VALUE_OPTIONS.has(a)) i++;
+    else if (a.startsWith("--")) { /* long option with =value or flag */ }
+    else if (a.startsWith("-")) { if (/^-[a-zA-Z]*a[a-zA-Z]*$/.test(a)) all = true; }
+    else block("`git commit <paths>` commits a tree other than the reviewed index. Stage the files, review, then run a plain `git commit`.");
+  }
+  target.all = all;
+}
+
+let tree;
+let common;
+let mergeBase;
+try {
+  common = git(["rev-parse", "--path-format=absolute", "--git-common-dir"]);
+  mergeBase = git(["merge-base", "origin/main", "HEAD"]);
+  if (!isCommit) {
+    tree = git(["rev-parse", "HEAD^{tree}"]);
+  } else if (target.all) {
+    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "precommit-gate-"));
+    try {
+      const tmp = path.join(dir, "index");
+      fs.copyFileSync(git(["rev-parse", "--path-format=absolute", "--git-path", "index"]), tmp);
+      git(["add", "-u"], { GIT_INDEX_FILE: tmp });
+      tree = git(["write-tree"], { GIT_INDEX_FILE: tmp });
+    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
+  } else {
+    tree = git(["write-tree"]);
+  }
+} catch {
+  process.exit(0); // not a git checkout (or no origin/main): let git report it
+}
+
+const verdictPath = path.join(common, "precommit-review", `${tree}.json`);
+let verdict = null;
+try { verdict = JSON.parse(fs.readFileSync(verdictPath, "utf8")); } catch { /* no verdict */ }
+if (verdict?.pass === true && verdict.base === mergeBase) process.exit(0);
+
+block(`no passing review (slop-reviewer and defect-reviewer) of the tree you are about to ${isCommit ? "commit" : "push"} (${tree}) against the merge-base ${mergeBase.slice(0, 12)}.
+${isCommit ? "Stage your change, then run: scripts/precommit-review.sh --staged" : "Run on the finished work before it goes to the remote: scripts/precommit-review.sh"}
+Fix every finding it reports (it passes only when slop is rated Low with zero findings and the defect reviewer reports none), then retry.${verdict ? `\nLast verdict for this exact tree: ${verdictPath} (pass=${verdict.pass}, base ${String(verdict.base).slice(0, 12)})` : ""}`);
